"""MockProvider — deterministic, network-free responses for tests (§12).

Two modes:
  * Scripted: pass `responses=[...]`; each `complete()` pops the next string.
  * Smart default: when no scripted response remains, it inspects the prompt and
    produces realistic structured JSON — heuristic question extraction for the
    extraction call, and keyword-grounded answers for the answering call. The
    grounding heuristic intentionally returns NEEDS_REVIEW when the KB context
    does not support a question, so the no-fabrication guardrail is exercised.
"""

from __future__ import annotations

import json
import re

from . import prompts

_STOPWORDS = {
    "do", "does", "is", "are", "have", "has", "the", "you", "your", "for",
    "and", "with", "what", "please", "provide", "attach", "of", "a", "an",
    "to", "in", "on", "we", "our", "most", "recent", "report",
    # Generic domain words that would otherwise create false "grounding" — the
    # mock should match on distinctive terms (e.g. "encryption", "incident"),
    # not on filler that appears in nearly every policy document.
    "data", "customer", "customers", "company", "system", "systems",
    "information", "service", "services", "use", "used", "all", "any",
}


def _answer_type(text: str) -> str:
    t = text.lower().strip()
    if any(w in t for w in ("attach", "upload", "provide your", "provide a copy")):
        return "attachment"
    if t.startswith(("do ", "does ", "is ", "are ", "have ", "has ", "can ", "will ", "did ")):
        return "yes_no"
    if t.startswith(("select", "which of", "choose")):
        return "multi_select"
    return "text"


def _content_words(text: str) -> set[str]:
    words = re.findall(r"[a-zA-Z0-9\-]+", text.lower())
    return {w for w in words if len(w) > 3 and w not in _STOPWORDS}


def _next_cell(location: str) -> str | None:
    """Heuristic answer anchor for an xlsx-style 'Sheet!B3': the cell to the
    right ('Sheet!C3'). Returns None for non-xlsx anchors."""
    m = re.match(r"^(.*!)([A-Za-z]+)(\d+)$", location or "")
    if not m:
        return None
    sheet, col, row = m.groups()
    # Increment the column letters (single/multi-letter).
    chars = list(col.upper())
    i = len(chars) - 1
    while i >= 0:
        if chars[i] == "Z":
            chars[i] = "A"
            i -= 1
            if i < 0:
                chars.insert(0, "A")
        else:
            chars[i] = chr(ord(chars[i]) + 1)
            break
    return f"{sheet}{''.join(chars)}{row}"


class MockProvider:
    def __init__(self, responses: list[str] | None = None):
        self._responses = list(responses or [])
        self.calls: list[tuple[str, str]] = []  # (system, user) for assertions

    def complete(
        self,
        system: str,
        user: str,
        *,
        max_tokens: int = 4096,
        temperature: float = 0.0,
    ) -> str:
        self.calls.append((system, user))
        if self._responses:
            return self._responses.pop(0)

        if system.startswith("You extract questions"):
            return self._mock_extract(user)
        if system.startswith("Answer STRICTLY"):
            # Style-aware ONLY for length/tone — never for whether to answer.
            slow = system.lower()
            style = "detailed" if "detailed" in slow else "concise" if "concise" in slow else None
            return self._mock_answer(user, style=style)
        if system.startswith("You are a strict faithfulness verifier"):
            return self._mock_faithfulness(user)
        if system.startswith("You are grading answers"):
            return self._mock_correctness(user)
        if system.startswith("A questionnaire item is ambiguous"):
            return self._mock_interpretations(user)
        if system.startswith("You compare pairs of answers"):
            return self._mock_conflicts(user)
        # doctor preflight uses a tiny JSON echo request.
        return '{"ok": true}'

    # --- conflict judge --------------------------------------------------
    def _mock_conflicts(self, user: str) -> str:
        """Conservative default: the mock cannot adjudicate nuance, so it reports
        NO conflict for every pair (the cheap heuristics in core/conflicts.py
        catch the clear contradictions without the judge). This avoids
        false-positive review noise."""
        try:
            start, end = user.find("["), user.rfind("]")
            items = json.loads(user[start : end + 1]) if start != -1 else []
        except (json.JSONDecodeError, ValueError):
            items = []
        return json.dumps([{"id": str(it.get("id", "")), "conflict": False, "why": ""} for it in items])

    # --- interpretations -------------------------------------------------
    def _mock_interpretations(self, user: str) -> str:
        """Draft one keyword-grounded answer per interpretation (same grounding
        heuristic as _mock_answer)."""
        kb_context, payload = self._split_answer_user(user)
        kb_lower = kb_context.lower()
        kb_lines = [ln.strip() for ln in kb_context.splitlines() if ln.strip()]
        interps = []
        if isinstance(payload, dict):
            interps = payload.get("interpretations") or []
        out = []
        for interp in interps:
            words = _content_words(str(interp))
            overlap = {w for w in words if w in kb_lower}
            if len(overlap) >= 2:
                snippet = next(
                    (ln for ln in kb_lines if any(w in ln.lower() for w in overlap)),
                    kb_lines[0] if kb_lines else "",
                )
                out.append({
                    "interpretation": interp,
                    "answer": f"For '{interp}': {snippet}",
                    "citations": [{"source": "knowledge-base", "snippet": snippet}],
                    "status": "answered",
                })
            else:
                out.append({
                    "interpretation": interp,
                    "answer": "",
                    "citations": [],
                    "status": "needs_review",
                })
        return json.dumps(out)

    # --- eval correctness ------------------------------------------------
    def _mock_correctness(self, user: str) -> str:
        """A key fact is 'covered' if its content words appear in the answer."""
        try:
            start, end = user.find("["), user.rfind("]")
            items = json.loads(user[start : end + 1]) if start != -1 else []
        except (json.JSONDecodeError, ValueError):
            items = []
        out = []
        for it in items:
            answer_lower = str(it.get("answer", "")).lower()
            covered, missing = [], []
            for fact in it.get("key_facts") or []:
                fact_words = _content_words(str(fact))
                if fact_words and all(w in answer_lower for w in fact_words):
                    covered.append(fact)
                else:
                    missing.append(fact)
            out.append({"id": str(it.get("id", "")), "covered_facts": covered, "missing_facts": missing})
        return json.dumps(out)

    # --- faithfulness ----------------------------------------------------
    def _mock_faithfulness(self, user: str) -> str:
        """Honest verdict for the mock's own answers: a claim is faithful when
        its words actually appear in the cited snippets (which the mock answerer
        guarantees, since it answers WITH a snippet). This keeps the mock truthful
        rather than rubber-stamping."""
        items = []
        try:
            start, end = user.find("["), user.rfind("]")
            items = json.loads(user[start : end + 1]) if start != -1 else []
        except (json.JSONDecodeError, ValueError):
            items = []
        out = []
        for it in items:
            answer = str(it.get("answer", ""))
            snippets = " ".join(str(s) for s in (it.get("snippets") or []))
            snip_lower = snippets.lower()
            claim_words = _content_words(answer)
            # Faithful if the answer's content words are largely present in the
            # cited snippets (entailment proxy).
            if not claim_words:
                faithful = bool(snippets)
            else:
                present = sum(1 for w in claim_words if w in snip_lower)
                faithful = present / len(claim_words) >= 0.5
            out.append(
                {
                    "id": str(it.get("id", "")),
                    "faithful": faithful,
                    "unsupported_claims": [] if faithful else ["answer not entailed by snippets"],
                }
            )
        return json.dumps(out)

    # --- extraction ------------------------------------------------------
    def _mock_extract(self, user: str) -> str:
        items: list[dict] = []
        current_section: str | None = None
        n = 0
        for raw in user.splitlines():
            line = raw.strip()
            if not line.startswith("- ") or " = " not in line:
                continue
            location, _, rest = line[2:].partition(" = ")
            location = location.strip()
            # Split off trailing "  [flags]".
            flags = ""
            m = re.search(r"\s\[([^\]]+)\]\s*$", rest)
            if m:
                flags = m.group(1)
                rest = rest[: m.start()].strip()
            text = rest.strip()
            is_question = text.endswith("?") or _answer_type(text) == "attachment"
            is_section = ("section" in flags or "merged" in flags) and not is_question
            if is_section:
                current_section = text
                continue
            if not is_question:
                continue
            n += 1
            items.append(
                {
                    "id": f"q{n}",
                    "question_text": text,
                    "answer_type": _answer_type(text),
                    "section": current_section,
                    "location_hint": location,
                    "answer_location_hint": _next_cell(location),
                    "ambiguous": False,
                    "interpretations": [],
                }
            )
        return json.dumps(items)

    # --- answering -------------------------------------------------------
    def _mock_answer(self, user: str, style: str | None = None) -> str:
        kb_context, questions = self._split_answer_user(user)
        kb_lower = kb_context.lower()
        kb_lines = [ln.strip() for ln in kb_context.splitlines() if ln.strip()]
        out: list[dict] = []
        for q in questions:
            qtext = q.get("question_text", "")
            atype = q.get("answer_type", "text")
            qid = q.get("question_id") or q.get("id")
            if atype == "attachment":
                # Phase 0 does not resolve attachments; flag for review.
                out.append(
                    {
                        "question_id": qid,
                        "answer": "",
                        "answer_type": atype,
                        "citations": [],
                        "confidence": "low",
                        "status": "needs_review",
                        "review_reason": "attachment_unresolved",
                        "missing_info": "Attachment request — resolve the document manually (Phase 2).",
                        "source_tier": None,
                    }
                )
                continue

            words = _content_words(qtext)
            overlap = {w for w in words if w in kb_lower}
            if len(overlap) >= 2:
                snippet = next(
                    (ln for ln in kb_lines if any(w in ln.lower() for w in overlap)),
                    kb_lines[0] if kb_lines else "",
                )
                # Style affects ONLY length/tone of a SUPPORTED answer — never
                # whether to answer, and the citation is always present. The
                # "detailed" variant restates the SAME grounded fact at greater
                # length (it adds no claims beyond the snippet, so it stays
                # faithful).
                if style == "detailed":
                    answer = f"Based on the knowledge base: {snippet} In detail: {snippet}"
                elif style == "concise":
                    answer = snippet
                else:
                    answer = f"Based on the knowledge base: {snippet}"
                out.append(
                    {
                        "question_id": qid,
                        "answer": answer,
                        "answer_type": atype,
                        "citations": [{"source": "knowledge-base", "snippet": snippet}],
                        "confidence": "medium",
                        "status": "answered",
                        "review_reason": "none",
                        "missing_info": None,
                        "source_tier": 2,
                    }
                )
            else:
                out.append(
                    {
                        "question_id": qid,
                        "answer": "",
                        "answer_type": atype,
                        "citations": [],
                        "confidence": "low",
                        "status": "needs_review",
                        "review_reason": "unsupported",
                        "missing_info": f"No knowledge base content supports: '{qtext}'.",
                        "source_tier": None,
                    }
                )
        return json.dumps(out)

    @staticmethod
    def _split_answer_user(user: str) -> tuple[str, list[dict]]:
        kb_context = ""
        questions: list[dict] = []
        if prompts.QUESTIONS_MARKER in user:
            ctx_part, _, q_part = user.partition(prompts.QUESTIONS_MARKER)
            # Strip the SafeRAG DATA delimiters (Part C) before parsing.
            for token in (prompts.KB_CONTEXT_MARKER, prompts.DATA_OPEN, prompts.DATA_CLOSE):
                ctx_part = ctx_part.replace(token, "")
                q_part = q_part.replace(token, "")
            kb_context = ctx_part.strip()
            try:
                questions = json.loads(q_part.strip())
            except json.JSONDecodeError:
                # Fall back to the outermost JSON span if wrappers remain.
                lo = q_part.find("[") if "[" in q_part else q_part.find("{")
                hi = max(q_part.rfind("]"), q_part.rfind("}"))
                if lo != -1 and hi != -1 and hi > lo:
                    try:
                        questions = json.loads(q_part[lo : hi + 1])
                    except json.JSONDecodeError:
                        questions = []
        return kb_context, questions

"""OAuth 2.0 (Authorization Code + PKCE) for the source connectors (Phase 12).

Lets a user connect Notion / Google Drive / Confluence by clicking "Sign in" and
consenting in their own browser, instead of pasting a personal token. The flow is
standard Authorization Code + PKCE:

  1. /api/oauth/{provider}/start  → build the provider authorize URL (state + PKCE)
  2. user logs in + consents on the provider
  3. /api/oauth/callback          → exchange the code for a token, store it SERVER-SIDE

Boundaries: the OAuth **client secret never leaves the server**, and the resulting
**access token is never sent to the browser** — it's persisted server-side and used
only by an explicit `connect`. OAuth still needs a one-time registered OAuth app per
provider (client_id/secret in config); this module can't create that. The HTTP
exchange is injectable so the whole flow is testable offline.
"""

from __future__ import annotations

import base64
import hashlib
import json
import secrets
from pathlib import Path
from urllib.parse import urlencode

# Per-provider OAuth endpoints + the config fields holding their client credentials.
OAUTH_SPECS: dict[str, dict] = {
    "notion": {
        "label": "Notion",
        "authorize_url": "https://api.notion.com/v1/oauth/authorize",
        "token_url": "https://api.notion.com/v1/oauth/token",
        "scopes": [],  # Notion grants at the integration level, not per-scope
        "extra_authorize": {"owner": "user"},
        "client_auth": "basic",  # token endpoint uses HTTP Basic client auth
        "id_field": "notion_client_id", "secret_field": "notion_client_secret",
    },
    "gdrive": {
        "label": "Google Drive",
        "authorize_url": "https://accounts.google.com/o/oauth2/v2/auth",
        "token_url": "https://oauth2.googleapis.com/token",
        "scopes": ["https://www.googleapis.com/auth/drive.readonly"],
        "extra_authorize": {"access_type": "offline", "prompt": "consent"},
        "client_auth": "post",
        "id_field": "google_client_id", "secret_field": "google_client_secret",
    },
    "confluence": {
        "label": "Confluence",
        "authorize_url": "https://auth.atlassian.com/authorize",
        "token_url": "https://auth.atlassian.com/oauth/token",
        # Granular scopes for the Confluence Cloud REST API v2 (classic v1 scopes are
        # retired). read:space + read:page cover listing spaces and reading page bodies.
        "scopes": ["read:space:confluence", "read:page:confluence", "offline_access"],
        "extra_authorize": {"audience": "api.atlassian.com", "prompt": "consent"},
        "client_auth": "post",
        "id_field": "confluence_client_id", "secret_field": "confluence_client_secret",
    },
    "microsoft": {
        "label": "Microsoft 365",
        "authorize_url": "https://login.microsoftonline.com/common/oauth2/v2.0/authorize",
        "token_url": "https://login.microsoftonline.com/common/oauth2/v2.0/token",
        "scopes": ["Files.Read.All", "Sites.Read.All", "offline_access"],
        "extra_authorize": {"prompt": "consent"},
        "client_auth": "post",
        "id_field": "microsoft_client_id", "secret_field": "microsoft_client_secret",
    },
}

# Connection type → the OAuth provider it authenticates through (SharePoint and
# OneDrive both ride Microsoft identity / Graph).
CONNECTOR_OAUTH = {
    "gdrive": "gdrive", "notion": "notion", "confluence": "confluence",
    "sharepoint": "microsoft", "onedrive": "microsoft",
}


class OAuthError(RuntimeError):
    pass


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def make_pkce() -> tuple[str, str]:
    """(code_verifier, code_challenge) using S256 — RFC 7636."""
    verifier = _b64url(secrets.token_bytes(32))
    challenge = _b64url(hashlib.sha256(verifier.encode("ascii")).digest())
    return verifier, challenge


def make_state() -> str:
    return secrets.token_urlsafe(24)


def client_credentials(config, provider: str) -> tuple[str, str]:
    spec = OAUTH_SPECS[provider]
    return (getattr(config, spec["id_field"], "") or "",
            getattr(config, spec["secret_field"], "") or "")


def is_configured(config, provider: str) -> bool:
    cid, secret = client_credentials(config, provider)
    return bool(cid and secret)


def authorize_url(provider: str, client_id: str, redirect_uri: str, state: str, challenge: str) -> str:
    spec = OAUTH_SPECS[provider]
    params = {
        "response_type": "code", "client_id": client_id, "redirect_uri": redirect_uri,
        "state": state, "code_challenge": challenge, "code_challenge_method": "S256",
    }
    if spec["scopes"]:
        params["scope"] = " ".join(spec["scopes"])
    params.update(spec.get("extra_authorize", {}))
    return spec["authorize_url"] + "?" + urlencode(params)


def _http_post_form(url: str, data: dict, headers: dict) -> dict:  # pragma: no cover - real network
    import urllib.request

    body = urlencode(data).encode("utf-8")
    req = urllib.request.Request(url, data=body, headers={
        "Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json", **headers})
    with urllib.request.urlopen(req, timeout=20) as resp:  # noqa: S310 - explicit token endpoint
        return json.loads(resp.read().decode("utf-8"))


def exchange_code(provider: str, code: str, client_id: str, client_secret: str,
                  redirect_uri: str, verifier: str, fetch=None) -> dict:
    """Trade the auth code for a token dict. `fetch(url, data, headers)->dict` is
    injectable so tests never hit the network. Raises OAuthError on a provider error."""
    spec = OAUTH_SPECS[provider]
    data = {"grant_type": "authorization_code", "code": code, "redirect_uri": redirect_uri,
            "code_verifier": verifier, "client_id": client_id}
    headers: dict = {}
    if spec["client_auth"] == "basic":
        token = base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()
        headers["Authorization"] = f"Basic {token}"
    else:
        data["client_secret"] = client_secret
    resp = (fetch or _http_post_form)(spec["token_url"], data, headers)
    if not isinstance(resp, dict) or "access_token" not in resp:
        raise OAuthError(f"{spec['label']}: token exchange failed ({resp.get('error') if isinstance(resp, dict) else 'no token'}).")
    return resp


def refresh_access_token(provider: str, refresh_tok: str, client_id: str, client_secret: str,
                         fetch=None) -> dict:
    """Use a refresh token to mint a fresh access token so long-lived connections
    don't silently die. Providers may or may not rotate the refresh token — if the
    response omits one, the caller keeps the existing refresh_token. Server-side only."""
    spec = OAUTH_SPECS[provider]
    if not refresh_tok:
        raise OAuthError(f"{spec['label']}: no refresh token stored — reconnect.")
    data = {"grant_type": "refresh_token", "refresh_token": refresh_tok, "client_id": client_id}
    headers: dict = {}
    if spec["client_auth"] == "basic":
        token = base64.b64encode(f"{client_id}:{client_secret}".encode()).decode()
        headers["Authorization"] = f"Basic {token}"
    else:
        data["client_secret"] = client_secret
    if spec["scopes"]:
        data["scope"] = " ".join(spec["scopes"])
    resp = (fetch or _http_post_form)(spec["token_url"], data, headers)
    if not isinstance(resp, dict) or "access_token" not in resp:
        raise OAuthError(f"{spec['label']}: token refresh failed.")
    return resp


def is_auth_error(exc: Exception) -> bool:
    """Heuristic: did a connector fetch fail because the access token expired (401)?
    Kept string-based so it works across urllib / requests / SDK error shapes."""
    code = getattr(exc, "code", None) or getattr(getattr(exc, "response", None), "status_code", None)
    if code in (401, 403):
        return True
    s = str(exc).lower()
    return "401" in s or "unauthorized" in s or "invalid_grant" in s or "token expired" in s or "invalidauthenticationtoken" in s


def atlassian_cloud_id(access_token: str, fetch=None) -> str | None:  # pragma: no cover - real network
    """Resolve the Atlassian Cloud id for an OAuth token (needed to address the
    Confluence Cloud API at api.atlassian.com/ex/confluence/{cloudId})."""
    def _default(url, headers):
        import urllib.request

        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=20) as resp:  # noqa: S310
            return json.loads(resp.read().decode("utf-8"))

    data = (fetch or _default)("https://api.atlassian.com/oauth/token/accessible-resources",
                              {"Authorization": f"Bearer {access_token}", "Accept": "application/json"})
    if isinstance(data, list) and data:
        return data[0].get("id")
    return None


class TokenStore:
    """Persists OAuth tokens server-side, one file per provider. Never returned to
    the browser. Account-level (this is a local, single-user tool)."""

    def __init__(self, directory):
        self.dir = Path(directory)

    def _path(self, provider: str) -> Path:
        return self.dir / f"{provider}.json"

    def save(self, provider: str, token: dict) -> None:
        self.dir.mkdir(parents=True, exist_ok=True)
        self._path(provider).write_text(json.dumps(token), encoding="utf-8")

    def load(self, provider: str) -> dict | None:
        p = self._path(provider)
        if not p.exists():
            return None
        try:
            return json.loads(p.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            return None

    def has(self, provider: str) -> bool:
        tok = self.load(provider)
        return bool(tok and tok.get("access_token"))

    def access_token(self, provider: str) -> str | None:
        tok = self.load(provider)
        return (tok or {}).get("access_token")

    def forget(self, provider: str) -> None:
        p = self._path(provider)
        if p.exists():
            p.unlink()

"""Embeddings interface, defaulting to a LOCAL model so the fully-local path
makes zero external network calls (§4.7, §12). sentence-transformers is imported
lazily; wired into retrieval in Phase 1.
"""

from __future__ import annotations

from typing import Protocol, runtime_checkable


@runtime_checkable
class Embedder(Protocol):
    def embed(self, texts: list[str]) -> list[list[float]]: ...


class LocalEmbedder:
    """Local sentence-transformers embedder. First run downloads the model."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        self.model_name = model_name
        self._model = None

    def _load(self):
        if self._model is None:
            try:
                from sentence_transformers import SentenceTransformer
            except ImportError as exc:  # pragma: no cover - import guard
                raise RuntimeError(
                    "sentence-transformers is not installed. "
                    'Install it with: pip install "qresponder[retrieval]"'
                ) from exc
            self._model = SentenceTransformer(self.model_name)
        return self._model

    def embed(self, texts: list[str]) -> list[list[float]]:
        model = self._load()
        vecs = model.encode(texts, normalize_embeddings=True, show_progress_bar=False)
        return [list(map(float, v)) for v in vecs]

"""Anthropic provider (§12). Imports the SDK lazily so the package installs and
imports without `anthropic` present (tests use MockProvider, no network)."""

from __future__ import annotations

from .base import ProviderError, with_retry


class AnthropicProvider:
    def __init__(self, api_key: str, model: str):
        if not api_key:
            raise ProviderError(
                "ANTHROPIC_API_KEY is empty. Set it in .env or the environment."
            )
        self.model = model
        self._api_key = api_key
        self._client = None  # lazy

    def _get_client(self):
        if self._client is None:
            try:
                import anthropic
            except ImportError as exc:  # pragma: no cover - import guard
                raise ProviderError(
                    "The 'anthropic' package is not installed. "
                    'Install it with: pip install "qresponder[anthropic]"'
                ) from exc
            self._client = anthropic.Anthropic(api_key=self._api_key)
        return self._client

    def complete(
        self,
        system: str,
        user: str,
        *,
        max_tokens: int = 4096,
        temperature: float = 0.0,
    ) -> str:
        client = self._get_client()

        def _call() -> str:
            resp = client.messages.create(
                model=self.model,
                system=system,
                messages=[{"role": "user", "content": user}],
                max_tokens=max_tokens,
                temperature=temperature,
            )
            return resp.content[0].text

        return with_retry(_call)

"""LLM provider interface + shared retry helper (§4.5, §12).

GUARDRAIL: all core logic depends on the `LLMProvider` Protocol, never a
concrete SDK. Providers are constructed from Config in `factory()`.
"""

from __future__ import annotations

import time
from typing import Callable, Protocol, runtime_checkable


@runtime_checkable
class LLMProvider(Protocol):
    def complete(
        self,
        system: str,
        user: str,
        *,
        max_tokens: int = 4096,
        temperature: float = 0.0,
    ) -> str: ...


class ProviderError(RuntimeError):
    """Raised for provider misconfiguration or repeated call failure."""


def with_retry(fn: Callable[[], str], *, attempts: int = 2, base_delay: float = 1.0) -> str:
    """Call `fn` with one retry + linear backoff (§12: one retry+backoff).

    Re-raises the last exception wrapped in ProviderError on persistent failure.
    """
    last_exc: Exception | None = None
    for i in range(attempts):
        try:
            return fn()
        except Exception as exc:  # noqa: BLE001 - normalize to ProviderError
            last_exc = exc
            if i < attempts - 1:
                time.sleep(base_delay * (i + 1))
    raise ProviderError(f"LLM call failed after {attempts} attempt(s): {last_exc}") from last_exc


def make_provider(config) -> LLMProvider:
    """Construct the default provider from config.llm_provider (Phase 8: routes
    anthropic | openai | gemini | deepseek | local | mock via the registry)."""
    from .providers import PROVIDER_SPECS, canonical, make_provider_for

    p = canonical(config.llm_provider)
    if p != "mock" and p not in PROVIDER_SPECS:
        raise ProviderError(
            f"Unknown LLM_PROVIDER '{config.llm_provider}'. Use one of: "
            "anthropic, openai, gemini, deepseek, local, mock."
        )
    return make_provider_for(config, p, None)
